#pragma once

#include "sim/mechanism_kit.hpp"

namespace scraperx::sim {
// The existing solid Kellerworks shaft. Presentation mirrors these bounds;
// its facade collision is regenerated by solid_export.gd, never translated
// in the generated table. The main frame's nominal north edge is z=-176.
//
// The crew's bridge between the shafts at the 220 ring is broken
// (03_EXECUTION/SECOND_TOWER/BROKEN_BRIDGE.md): its near half stands out
// from the 220 ring, its far half out from the shaft's brackets, and the
// 18 m between them is open. Over the gap's middle reaches the shaft's old
// erection arm, a yellow bar across its tip: hooked from either tip, the
// line swings a body across the gap to the other tip, where the swing
// spends itself (a pendulum hung over the middle carries a body to the
// height it started from, as far beyond as it started before). The drop-in
// leaf that closed the gap stands raised on the far half's west lane,
// leaning toward the gap, held by a catch whose trip is a steel flag hung
// in a hood behind it, the hood open only toward the shaft. Swing the flag
// in with a hook shot from the shaft's side and the leaf comes down across
// the gap onto the near half, for good.
struct TwinTower final {
    static constexpr double kCenterZ = -264.0;
    static constexpr double kFaceZ = kCenterZ + 40.0;
    static constexpr std::uint64_t kFrameEntity = 1949;
    static constexpr std::uint64_t kLeafEntity = 2660;
    static constexpr std::uint64_t kFlagEntity = 2661;
    static constexpr float kDeckTop = 220.25F;
    static constexpr float kInclineTop = 224.25F;
    static constexpr float kLandingTop = 225.65F;
    // The two halves' tips and the open gap between them (z, metres).
    static constexpr float kNearTipZ = -190.0F;
    static constexpr float kFarTipZ = -208.0F;
    // Both halves' decks, two lanes wide: the west lane carries the leaf,
    // the east lane is where the swing starts and lands.
    static constexpr float kDeckWestX = -10.0F;
    static constexpr float kDeckEastX = -3.6F;
    static constexpr float kLeafWestX = -9.8F;
    static constexpr float kLeafEastX = -7.6F;
    static constexpr float kSwingX = -5.0F;
    // The erection arm: out from the shaft's face over the gap's middle, its
    // top this high; the bar across its tip is the hook's mark.
    static constexpr float kArmTipZ = 0.5F * (kNearTipZ + kFarTipZ);
    static constexpr float kArmY = 232.0F;
    static constexpr float kBarHalfLength = 1.4F;
    // A steel step at each tip to swing from, 1 m square and this tall, set
    // at the tip's edge, side by side with where the other way lands (the
    // near one west of the lane's middle, the far one east). On the line,
    // the feet sweep a circle about the bar; from a step it passes over the
    // other tip's edge, and the swing tops out this high over its deck.
    static constexpr float kStepHeight = 1.2F;
    static constexpr float kNearStepWestX = -6.2F;
    static constexpr float kFarStepWestX = -4.6F;
    // The leaf's hinge, across the far half 2.3 m back from its tip, under
    // the leaf's girders (kLeafDepth below the deck's top), as a bascule's
    // is: raised, its heel stands in a pit cut in the far half's west lane;
    // down, its roadway lies level with the deck and reaches 1 m onto the
    // near half.
    static constexpr float kHingeZ = kFarTipZ - 2.3F;
    static constexpr float kLeafDepth = 0.62F;
    static constexpr float kLeafLength = kNearTipZ - kHingeZ + 1.0F;
    // Raised, it leans this far past upright toward the gap (CHOSEN: enough
    // that, let go, its own weight starts it down at once).
    static constexpr float kLeafLeanRad = 0.14F;
    static constexpr float kLeafMassKg = 6000.0F;
    // Its hydraulic buffer (declared model: angular damping on the leaf, per
    // second; CHOSEN so it comes down in about nine seconds and lands with
    // its tip under 6 m/s).
    static constexpr float kLeafBufferPerS = 2.5F;
    // The trip: a steel flag hung by its top edge in a hood on a post behind
    // the leaf, the hood's back toward the gap and its mouth toward the
    // shaft. Swung in past kFlagReleaseRad, it pulls the catch's pin. Its
    // pivot is out of a climber's reach from the deck below (a hang catches
    // at most 3.79 m over the feet).
    static constexpr float kFlagMassKg = 4.0F;
    static constexpr float kFlagReleaseRad = 0.35F;
    static constexpr float kFlagX = 0.5F * (kLeafWestX + kLeafEastX);
    static constexpr float kFlagZ = kHingeZ - 2.6F;
    static constexpr float kFlagPivotY = kDeckTop + 5.0F;
    static constexpr float kFlagHalfWidth = 0.3F;
    static constexpr float kFlagHalfHeight = 0.3F;

    struct Built final {
        kit::BodyIndex frame;
        kit::BodyIndex leaf;
        kit::BodyIndex flag;
        kit::LeverIndex hinge;
        kit::LeverIndex flag_hinge;
        kit::CatchIndex catch_index;
    };
    static Built build(kit::Kit &kit);
};
} // namespace scraperx::sim
